  {
    SELECT DISTINCT ?professor ?professorName ?country
    WHERE {
      ?professor a uni:Professor ;
                 uni:hasName ?professorName ;
                 uni:hasRank "full" ;
                 uni:worksInDepartment ?department .

      ?department a uni:Department ;
